// sketch-curve: a quadratic Bézier from (0, 0) through the control point (10, 20) to (30, 0), and a curve made of it
export function c008(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skBezier(s1, "bezier1", { "points" : [vector(0, 0) * millimeter, vector(10, 20) * millimeter, vector(30, 0) * millimeter] });
    skSolve(s1);
    compositeCurve(context, id + "curve1", { "edges" : qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE) });
    return { "sketch" : wireProbe(context, qCreatedBy(id + "s1", EntityType.BODY)), "curve" : wireProbe(context, qCreatedBy(id + "curve1", EntityType.BODY)) };
}

// trim-curve: a quartic Bézier from (0, 0) to (30, 0) extended 10 mm at its end, straight on
export function c009(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skBezier(s1, "bezier1", { "points" : [vector(0, 0) * millimeter, vector(5, 15) * millimeter, vector(15, 20) * millimeter, vector(25, 15) * millimeter, vector(30, 0) * millimeter] });
    skSolve(s1);
    compositeCurve(context, id + "curve1", { "edges" : qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE) });
    trimCurve(context, id + "trim1", { "moveBoundaryType" : MoveCurveBoundaryType.EXTEND, "wires" : qCreatedBy(id + "curve1", EntityType.BODY), "flipHeuristics" : false, "helpPoint" : qContainsPoint(qOwnedByBody(qCreatedBy(id + "curve1", EntityType.BODY), EntityType.VERTEX), vector(30, 0, 0) * millimeter), "endCondition" : CurveExtensionEndCondition.BLIND, "extensionDistance" : 10 * millimeter, "extensionShape" : CurveExtensionShape.TANGENT });
    return { "before" : wireProbe(context, qCreatedBy(id + "s1", EntityType.BODY)), "edges" : wireProbe(context, qCreatedBy(id + "curve1", EntityType.BODY)) };
}

// isocline: half a torus (revolved 180°) split at its 20 degree isoclines, the direction tilted 30° from its axis
export function c010(context is Context, id is Id)
{
    const profile = newSketchOnPlane(context, id + "profile", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skCircle(profile, "c1", { "center" : vector(10, 0) * millimeter, "radius" : 3 * millimeter });
    skSolve(profile);
    const axis = newSketchOnPlane(context, id + "axis", { "sketchPlane" : plane(vector(0, 0, -50) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(axis, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(100, 0) * millimeter });
    skSolve(axis);
    revolve(context, id + "base", { "entities" : qSketchRegion(id + "profile"), "axis" : qCreatedBy(id + "axis", EntityType.EDGE), "fullRevolve" : false, "endBound" : RevolveBoundingType.BLIND, "oppositeDirection" : false, "angle" : 180 * degree });
    const up = newSketchOnPlane(context, id + "up", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 0.5, 0.866025)) });
    skLineSegment(up, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(1, 0) * millimeter });
    skSolve(up);
    isocline(context, id + "iso1", { "faces" : qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.TORUS), "direction" : qCreatedBy(id + "up", EntityType.EDGE), "oppositeDirection" : false, "angle" : 20 * degree, "split" : true });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID)) };
}

// pcb: a flex PCB plate (0.2 mm) with flanges on two sides, finished with one bend unfolded holding its top, and its bend lines
export function c011(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s1, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(s1);
    pcbStart(context, id + "sm1", { "thickness" : 0.2 * millimeter, "oppositeDirection" : false, "radius" : 1 * millimeter, "flipDirectionUp" : false, "kFactor" : 0.5, "process" : SMProcessType.THICKEN, "regions" : qSketchRegion(id + "s1"), "tangentPropagation" : false, "bends" : qNothing() });
    sheetMetalFlange(context, id + "flange1", { "edges" : qUnion([qClosestTo(qOwnedByBody(qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(40, 15, 0.2) * millimeter), qClosestTo(qOwnedByBody(qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(20, 30, 0.2) * millimeter)]), "flangeAlignment" : SMFlangeAlignment.INNER, "limitType" : SMFlangeBoundingType.BLIND, "distance" : 15 * millimeter, "angleControlType" : SMFlangeAngleControlType.BEND_ANGLE, "oppositeDirection" : false, "bendAngle" : 90 * degree, "autoMiter" : true, "useDefaultRadius" : true });
    pcbEnd(context, id + "end1", { "unfoldType" : PcbUnfoldType.UNFOLD_SELECTED, "pcbPart" : qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), "entitiesToUnfold" : qClosestTo(qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.CYLINDER), vector(41, 15, 1) * millimeter), "holdEntity" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(20, 15, 0.2) * millimeter) });
    return { "counts" : bodyCounts(context), "bendLines" : pcbBendLines(context) };
}

// sheet-metal-flat: batch 069's half tube with a flange, a 6 mm circle cut out of the middle of its flat pattern
export function c012(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skArc(s1, "a1", { "start" : vector(20, 0) * millimeter, "mid" : vector(0, 20) * millimeter, "end" : vector(-20, 0) * millimeter });
    skSolve(s1);
    sheetMetalStart(context, id + "sm1", { "thickness" : 2 * millimeter, "oppositeDirection" : false, "radius" : 1 * millimeter, "flipDirectionUp" : false, "process" : SMProcessType.EXTRUDE, "sketchCurves" : qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "bendArcs" : qNothing(), "endBound" : SMExtrudeBoundingType.BLIND, "oppositeExtrudeDirection" : false, "depth" : 25 * millimeter, "symmetric" : false, "hasSecondDirection" : false });
    sheetMetalFlange(context, id + "flange1", { "edges" : qClosestTo(qOwnedByBody(qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(20, 0, 12.5) * millimeter), "flangeAlignment" : SMFlangeAlignment.INNER, "limitType" : SMFlangeBoundingType.BLIND, "distance" : 10 * millimeter, "angleControlType" : SMFlangeAngleControlType.BEND_ANGLE, "oppositeDirection" : false, "bendAngle" : 90 * degree, "autoMiter" : true, "useDefaultRadius" : true });
    const f = newSketch(context, id + "f", { "sketchPlane" : qCorrespondingInFlat(qLargest(qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.CYLINDER))) });
    skCircle(f, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 3 * millimeter });
    skSolve(f);
    extrude(context, id + "flat1", { "bodyType" : ExtendedToolBodyType.SOLID, "entities" : qSketchRegion(id + "f"), "domain" : OperationDomain.FLAT, "flatOperationType" : FlatOperationType.REMOVE, "endBound" : BoundingType.BLIND, "depth" : 2 * millimeter });
    return { "counts" : bodyCounts(context), "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID)) };
}
